data.formula:
(function() {
  var symPairs = [
    {s1: '>=', s2: '<'},
    {s1: '>',  s2: '<='},
    {s1: '<=', s2: '>'},
    {s1: '<',  s2: '>='}
  ];
  var pair = symPairs[Math.floor(Math.random() * symPairs.length)];
  var swapSym = Math.random() < 0.5;
  var symA = swapSym ? pair.s2 : pair.s1;
  var symB = swapSym ? pair.s1 : pair.s2;

  var negA = Math.random() < 0.5;
  var negB = !negA;

  var twoOccA = Math.random() < 0.5;
  var twoOccB = !twoOccA;

  var multA = Math.random() < 0.5;
  var multB = !multA;

  function flipSym(s) {
    if (s === '>=') return '<=';
    if (s === '<=') return '>=';
    if (s === '>')  return '<';
    if (s === '<')  return '>';
    return s;
  }

  function symHtml(s) {
    if (s === '>=') return '&ge;';
    if (s === '<=') return '&le;';
    if (s === '>')  return '&gt;';
    if (s === '<')  return '&lt;';
    return s;
  }

  function fmtTerm(val, isFirst) {
    if (isFirst) return String(val);
    return val >= 0 ? ' + ' + val : ' - ' + Math.abs(val);
  }

  function fmtXTerm(coeff, isFirst) {
    if (isFirst) {
      if (coeff === 1) return '<i>x</i>';
      if (coeff === -1) return '-<i>x</i>';
      return coeff + '<i>x</i>';
    } else {
      if (coeff === 1) return ' + <i>x</i>';
      if (coeff === -1) return ' - <i>x</i>';
      return coeff > 0 ? ' + ' + coeff + '<i>x</i>' : ' - ' + Math.abs(coeff) + '<i>x</i>';
    }
  }

  function fracHtml(num, den) {
    return '<span style="display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;margin:0 3px;line-height:1.15"><span style="border-bottom:1px solid #202b36;padding:0 4px">' + num + '</span><span style="padding:0 4px">' + den + '</span></span>';
  }

  function randInt(min, max, excludeZero) {
    var v;
    do {
      v = min + Math.floor(Math.random() * (max - min + 1));
    } while (excludeZero && v === 0);
    return v;
  }

  function buildProblem(isMult, isNeg, isTwoOcc, initSym) {
    var xSol = randInt(-14, 14, false);
    var finalSym = isNeg ? flipSym(initSym) : initSym;
    var eq, s1, s2, s3, s4;

    if (isMult && !isTwoOcc) {
      var a = (isNeg ? -1 : 1) * randInt(2, 5, false);
      var b = randInt(-6, 6, true);
      var c = randInt(-9, 9, true);
      var d = randInt(-9, 9, true);
      var rhs = a * (xSol + b) + c + d;
      var constSum = c + d;
      var distConst = a * b + constSum;
      var rhsAfterConst = rhs - distConst;

      eq = a + '(<i>x</i>' + fmtTerm(b, false) + ')' + fmtTerm(c, false) + fmtTerm(d, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s1 = 'Combine constants: ' + a + '(<i>x</i>' + fmtTerm(b, false) + ')' + fmtTerm(constSum, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s2 = 'Distribute: ' + fmtXTerm(a, true) + fmtTerm(distConst, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s3 = (distConst >= 0 ? 'Subtract ' + distConst : 'Add ' + Math.abs(distConst)) + ': ' + fmtXTerm(a, true) + ' ' + symHtml(initSym) + ' ' + rhsAfterConst;
      s4 = 'Divide by ' + a + (isNeg ? ' (flip sign)' : '') + ': <b><i>x</i> ' + symHtml(finalSym) + ' ' + xSol + '</b>';
    } else if (isMult && isTwoOcc) {
      var a1 = (isNeg ? -1 : 1) * randInt(3, 6, false);
      var a2 = (isNeg ? 1 : -1) * randInt(1, 2, false);
      var combCoeff = a1 + a2;
      if (combCoeff === 0) {
        a2 = isNeg ? 1 : -1;
        combCoeff = a1 + a2;
      }
      var b = randInt(-5, 5, true);
      var c = randInt(-10, 10, true);
      var rhs = a1 * (xSol + b) + a2 * xSol + c;
      var distConst = a1 * b + c;
      var rhsAfterConst = rhs - distConst;

      eq = a1 + '(<i>x</i>' + fmtTerm(b, false) + ')' + fmtXTerm(a2, false) + fmtTerm(c, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s1 = 'Distribute: ' + fmtXTerm(a1, true) + fmtTerm(a1 * b, false) + fmtXTerm(a2, false) + fmtTerm(c, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s2 = 'Combine like terms: ' + fmtXTerm(combCoeff, true) + fmtTerm(distConst, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s3 = (distConst >= 0 ? 'Subtract ' + distConst : 'Add ' + Math.abs(distConst)) + ': ' + fmtXTerm(combCoeff, true) + ' ' + symHtml(initSym) + ' ' + rhsAfterConst;
      s4 = 'Divide by ' + combCoeff + (combCoeff < 0 ? ' (flip sign)' : '') + ': <b><i>x</i> ' + symHtml(finalSym) + ' ' + xSol + '</b>';
    } else if (!isMult && !isTwoOcc) {
      var den = (isNeg ? -1 : 1) * randInt(2, 5, false);
      var k = randInt(-5, 5, false);
      var b = k * Math.abs(den) - xSol;
      var c = randInt(-8, 8, true);
      var d = randInt(-8, 8, true);
      var fracVal = (xSol + b) / den;
      var rhs = fracVal + c + d;
      var constSum = c + d;
      var rhsAfterConst = rhs - constSum;

      eq = fracHtml('<i>x</i>' + fmtTerm(b, false), den) + fmtTerm(c, false) + fmtTerm(d, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s1 = 'Combine constants: ' + fracHtml('<i>x</i>' + fmtTerm(b, false), den) + fmtTerm(constSum, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s2 = (constSum >= 0 ? 'Subtract ' + constSum : 'Add ' + Math.abs(constSum)) + ': ' + fracHtml('<i>x</i>' + fmtTerm(b, false), den) + ' ' + symHtml(initSym) + ' ' + rhsAfterConst;
      s3 = 'Multiply by ' + den + (isNeg ? ' (flip sign)' : '') + ': <i>x</i>' + fmtTerm(b, false) + ' ' + symHtml(finalSym) + ' ' + (rhsAfterConst * den);
      s4 = (b >= 0 ? 'Subtract ' + b : 'Add ' + Math.abs(b)) + ': <b><i>x</i> ' + symHtml(finalSym) + ' ' + xSol + '</b>';
    } else {
      var d1 = (isNeg ? -1 : 1) * 2;
      var d2 = (isNeg ? -1 : 1) * 4;
      var multStep = randInt(-4, 4, true);
      xSol = multStep * 4;
      var c1 = randInt(-7, 7, true);
      var c2 = randInt(-7, 7, true);
      var rhs = (xSol / d1) + (xSol / d2) + c1 + c2;
      var constSum = c1 + c2;
      var rhsAfterConst = rhs - constSum;
      var combCoeff = isNeg ? -3 : 3;

      eq = fracHtml('<i>x</i>', d1) + ' + ' + fracHtml('<i>x</i>', d2) + fmtTerm(c1, false) + fmtTerm(c2, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s1 = 'Combine constants: ' + fracHtml('<i>x</i>', d1) + ' + ' + fracHtml('<i>x</i>', d2) + fmtTerm(constSum, false) + ' ' + symHtml(initSym) + ' ' + rhs;
      s2 = (constSum >= 0 ? 'Subtract ' + constSum : 'Add ' + Math.abs(constSum)) + ': ' + fracHtml('<i>x</i>', d1) + ' + ' + fracHtml('<i>x</i>', d2) + ' ' + symHtml(initSym) + ' ' + rhsAfterConst;
      s3 = 'Multiply all terms by ' + (isNeg ? '-4 (flip sign)' : '4') + ': ' + fmtXTerm(combCoeff, true) + ' ' + symHtml(finalSym) + ' ' + (rhsAfterConst * (isNeg ? -4 : 4));
      s4 = 'Divide by ' + combCoeff + ': <b><i>x</i> ' + symHtml(finalSym) + ' ' + xSol + '</b>';
    }

    return {eq: eq, s1: s1, s2: s2, s3: s3, s4: s4, xSol: xSol, finalSym: finalSym};
  }

  function renderNumberLine(sol, sym) {
    var w = 360, h = 64, pad = 22, minV = -20, maxV = 20;
    var scale = (w - 2 * pad) / (maxV - minV);
    function xPos(v) { return pad + (v - minV) * scale; }
    var svg = '<svg width="100%" viewBox="0 0 ' + w + ' ' + h + '" style="max-width:360px;display:block;margin:6px auto 0 auto;font-family:Arial,sans-serif">';
    svg += '<line x1="' + (pad - 10) + '" y1="30" x2="' + (w - pad + 10) + '" y2="30" stroke="#202b36" stroke-width="1.5"/>';
    svg += '<polygon points="' + (pad - 14) + ',30 ' + (pad - 7) + ',26 ' + (pad - 7) + ',34" fill="#202b36"/>';
    svg += '<polygon points="' + (w - pad + 14) + ',30 ' + (w - pad + 7) + ',26 ' + (w - pad + 7) + ',34" fill="#202b36"/>';

    for (var v = minV; v <= maxV; v++) {
      var xp = xPos(v);
      var isMajor = (v % 5 === 0);
      var tickH = isMajor ? 6 : 3;
      svg += '<line x1="' + xp.toFixed(1) + '" y1="' + (30 - tickH) + '" x2="' + xp.toFixed(1) + '" y2="' + (30 + tickH) + '" stroke="#202b36" stroke-width="' + (isMajor ? '1.3' : '0.8') + '"/>';
      if (isMajor) {
        svg += '<text x="' + xp.toFixed(1) + '" y="50" font-size="10" text-anchor="middle" fill="#202b36">' + v + '</text>';
      }
    }

    if (sol !== null && sym !== null) {
      var cx = xPos(sol);
      var isRight = (sym === '>' || sym === '>=');
      var isClosed = (sym === '>=' || sym === '<=');
      var endX = isRight ? (w - pad + 10) : (pad - 10);
      svg += '<line x1="' + cx.toFixed(1) + '" y1="30" x2="' + endX + '" y2="30" stroke="#1a73e8" stroke-width="3.5"/>';
      if (isRight) {
        svg += '<polygon points="' + (w - pad + 14) + ',30 ' + (w - pad + 6) + ',25 ' + (w - pad + 6) + ',35" fill="#1a73e8"/>';
      } else {
        svg += '<polygon points="' + (pad - 14) + ',30 ' + (pad - 6) + ',25 ' + (pad - 6) + ',35" fill="#1a73e8"/>';
      }
      svg += '<circle cx="' + cx.toFixed(1) + '" cy="30" r="5" fill="' + (isClosed ? '#1a73e8' : '#ffffff') + '" stroke="#1a73e8" stroke-width="2.2"/>';
    }
    svg += '</svg>';
    return svg;
  }

  var pA = buildProblem(multA, negA, twoOccA, symA);
  var pB = buildProblem(multB, negB, twoOccB, symB);

  var cardStyle = 'flex:1;min-width:290px;border:1px solid #d0d7de;border-radius:6px;padding:10px 12px;background:#fafbfc;box-sizing:border-box';

  var qHtml = '<div style="display:flex;flex-wrap:wrap;gap:14px;margin-top:8px">' +
    '<div style="' + cardStyle + '"><div style="font-weight:bold;margin-bottom:6px;font-size:14px">A) &nbsp; ' + pA.eq + '</div>' + renderNumberLine(null, null) + '</div>' +
    '<div style="' + cardStyle + '"><div style="font-weight:bold;margin-bottom:6px;font-size:14px">B) &nbsp; ' + pB.eq + '</div>' + renderNumberLine(null, null) + '</div>' +
  '</div>';

  var aHtml = '<div style="display:flex;flex-wrap:wrap;gap:14px">' +
    '<div style="' + cardStyle + '">' +
      '<div style="font-weight:bold;margin-bottom:6px;font-size:14px">A) &nbsp; ' + pA.eq + '</div>' +
      '<div style="font-size:12.5px;line-height:1.55;margin-bottom:6px">' +
        '<div><b>Step 1:</b> ' + pA.s1 + '</div>' +
        '<div><b>Step 2:</b> ' + pA.s2 + '</div>' +
        '<div><b>Step 3:</b> ' + pA.s3 + '</div>' +
        '<div><b>Step 4:</b> ' + pA.s4 + '</div>' +
      '</div>' +
      renderNumberLine(pA.xSol, pA.finalSym) +
    '</div>' +
    '<div style="' + cardStyle + '">' +
      '<div style="font-weight:bold;margin-bottom:6px;font-size:14px">B) &nbsp; ' + pB.eq + '</div>' +
      '<div style="font-size:12.5px;line-height:1.55;margin-bottom:6px">' +
        '<div><b>Step 1:</b> ' + pB.s1 + '</div>' +
        '<div><b>Step 2:</b> ' + pB.s2 + '</div>' +
        '<div><b>Step 3:</b> ' + pB.s3 + '</div>' +
        '<div><b>Step 4:</b> ' + pB.s4 + '</div>' +
      '</div>' +
      renderNumberLine(pB.xSol, pB.finalSym) +
    '</div>' +
  '</div>';

  return {questionHtml: qHtml, answerHtml: aHtml};
})()

(function(){
  var pairs = [
    ['&ge;', '&lt;'],
    ['&gt;', '&le;'],
    ['&le;', '&gt;'],
    ['&lt;', '&ge;']
  ];
  var pair = pairs[Math.floor(Math.random() * pairs.length)];

  var x1 = -16 + Math.floor(Math.random() * 33);
  var x2 = -16 + Math.floor(Math.random() * 33);
  while (x2 === x1) {
    x2 = -16 + Math.floor(Math.random() * 33);
  }

  var items = [
    { label: 'A)', op: pair[0], x: x1 },
    { label: 'B)', op: pair[1], x: x2 }
  ];

  function drawNumberLine(xVal, op) {
    var w = 420, h = 76;
    var left = 26, right = 394;
    var span = right - left;
    var minVal = -20, maxVal = 20;
    function toX(v) {
      return left + ((v - minVal) / (maxVal - minVal)) * span;
    }
    var yAxis = 38;
    var svg = '<svg viewBox="0 0 ' + w + ' ' + h + '" style="width:100%;height:auto;display:block;font-family:Arial,sans-serif">';
    svg += '<line x1="' + (left - 12) + '" y1="' + yAxis + '" x2="' + (right + 12) + '" y2="' + yAxis + '" stroke="#59636e" stroke-width="1.5"/>';
    svg += '<polygon points="' + (left - 18) + ',' + yAxis + ' ' + (left - 10) + ',' + (yAxis - 4) + ' ' + (left - 10) + ',' + (yAxis + 4) + '" fill="#59636e"/>';
    svg += '<polygon points="' + (right + 18) + ',' + yAxis + ' ' + (right + 10) + ',' + (yAxis - 4) + ' ' + (right + 10) + ',' + (yAxis + 4) + '" fill="#59636e"/>';

    for (var v = minVal; v <= maxVal; v++) {
      var px = toX(v);
      var isMajor = (v % 5 === 0);
      var tickH = isMajor ? 7 : 3.5;
      var sw = (v === 0) ? 2 : 1;
      svg += '<line x1="' + px.toFixed(1) + '" y1="' + (yAxis - tickH) + '" x2="' + px.toFixed(1) + '" y2="' + (yAxis + tickH) + '" stroke="#59636e" stroke-width="' + sw + '"/>';
      if (isMajor) {
        svg += '<text x="' + px.toFixed(1) + '" y="' + (yAxis + 21) + '" font-size="11" text-anchor="middle" fill="#202b36"' + (v === 0 ? ' font-weight="bold"' : '') + '>' + v + '</text>';
      }
    }

    var cx = toX(xVal);
    var isRight = (op === '&gt;' || op === '&ge;');
    var isClosed = (op === '&le;' || op === '&ge;');
    var rayEnd = isRight ? (right + 12) : (left - 12);

    svg += '<line x1="' + cx.toFixed(1) + '" y1="' + yAxis + '" x2="' + rayEnd + '" y2="' + yAxis + '" stroke="#1a73e8" stroke-width="4"/>';
    if (isRight) {
      svg += '<polygon points="' + (right + 19) + ',' + yAxis + ' ' + (right + 9) + ',' + (yAxis - 6) + ' ' + (right + 9) + ',' + (yAxis + 6) + '" fill="#1a73e8"/>';
    } else {
      svg += '<polygon points="' + (left - 19) + ',' + yAxis + ' ' + (left - 9) + ',' + (yAxis - 6) + ' ' + (left - 9) + ',' + (yAxis + 6) + '" fill="#1a73e8"/>';
    }

    if (isClosed) {
      svg += '<circle cx="' + cx.toFixed(1) + '" cy="' + yAxis + '" r="5.5" fill="#1a73e8" stroke="#1a73e8" stroke-width="2"/>';
    } else {
      svg += '<circle cx="' + cx.toFixed(1) + '" cy="' + yAxis + '" r="5.5" fill="#ffffff" stroke="#1a73e8" stroke-width="2.5"/>';
    }

    svg += '</svg>';
    return svg;
  }

  var qCards = items.map(function(it) {
    return '<div style="flex:1;min-width:300px;border:1px solid #d0d7de;border-radius:6px;padding:10px 12px;background:#ffffff">' +
           '<div style="font-weight:bold;font-size:14px;color:#202b36;margin-bottom:6px">' + it.label + '</div>' +
           drawNumberLine(it.x, it.op) +
           '</div>';
  }).join('');

  var aCards = items.map(function(it) {
    var circleDesc = (it.op === '&le;' || it.op === '&ge;') ? 'Closed circle (includes ' + it.x + ')' : 'Open circle (excludes ' + it.x + ')';
    var dirDesc = (it.op === '&gt;' || it.op === '&ge;') ? 'Shaded right (greater than)' : 'Shaded left (less than)';
    return '<div style="flex:1;min-width:300px;border:1px solid #d0d7de;border-radius:6px;padding:10px 12px;background:#f8fafc">' +
           '<div style="font-weight:bold;font-size:14px;color:#202b36;margin-bottom:4px">' + it.label + ' <span style="font-size:16px;color:#1a73e8">x ' + it.op + ' ' + it.x + '</span></div>' +
           '<div style="font-size:12px;color:#59636e;margin-bottom:6px">' + circleDesc + ' &bull; ' + dirDesc + '</div>' +
           drawNumberLine(it.x, it.op) +
           '</div>';
  }).join('');

  return {
    questionHtml: '<div style="display:flex;flex-wrap:wrap;gap:12px;margin-top:8px">' + qCards + '</div>',
    answerHtml: '<div style="display:flex;flex-wrap:wrap;gap:12px">' + aCards + '</div>'
  };
})()

bundle.formula:
(function(){
  function randInt(min, max) {
    return min + Math.floor(Math.random() * (max - min + 1));
  }
  function pick(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
  }
  function fmtSign(n) {
    return n >= 0 ? '+ ' + n : '- ' + Math.abs(n);
  }
  function texSym(sym) {
    if (sym === '>=') return '\\geq';
    if (sym === '<=') return '\\leq';
    return sym;
  }
  function htmlSym(sym) {
    if (sym === '>=') return '&ge;';
    if (sym === '<=') return '&le;';
    if (sym === '>') return '&gt;';
    if (sym === '<') return '&lt;';
    return sym;
  }
  function flipSym(sym) {
    if (sym === '>=') return '<=';
    if (sym === '<=') return '>=';
    if (sym === '>') return '<';
    if (sym === '<') return '>';
    return sym;
  }
  function buildNumberLine(sol, sym, solved) {
    var width = 340, height = 64, pad = 22;
    var span = width - 2 * pad;
    var toX = function(val) {
      return pad + ((val + 20) / 40) * span;
    };
    var svg = '<svg viewBox="0 0 ' + width + ' ' + height + '" style="width:100%;max-width:340px;height:auto;display:block;margin:6px auto 0 auto;">';
    svg += '<line x1="' + (pad - 8) + '" y1="32" x2="' + (width - pad + 8) + '" y2="32" stroke="#202b36" stroke-width="1.5"/>';
    svg += '<polygon points="' + (pad - 12) + ',32 ' + (pad - 5) + ',28 ' + (pad - 5) + ',36" fill="#202b36"/>';
    svg += '<polygon points="' + (width - pad + 12) + ',32 ' + (width - pad + 5) + ',28 ' + (width - pad + 5) + ',36" fill="#202b36"/>';
    for (var v = -20; v <= 20; v++) {
      var x = toX(v);
      var major = (v % 5 === 0);
      var tickH = major ? 6 : 3;
      svg += '<line x1="' + x.toFixed(1) + '" y1="' + (32 - tickH) + '" x2="' + x.toFixed(1) + '" y2="' + (32 + tickH) + '" stroke="#202b36" stroke-width="' + (major ? '1.3' : '0.8') + '"/>';
      if (major) {
        svg += '<text x="' + x.toFixed(1) + '" y="50" text-anchor="middle" font-family="Arial,sans-serif" font-size="9.5" fill="#202b36">' + v + '</text>';
      }
    }
    if (solved) {
      var sx = toX(sol);
      var isRight = (sym === '>' || sym === '>=');
      var isClosed = (sym === '>=' || sym === '<=');
      var endX = isRight ? (width - pad + 9) : (pad - 9);
      svg += '<line x1="' + sx.toFixed(1) + '" y1="32" x2="' + endX + '" y2="32" stroke="#1d6fd8" stroke-width="3.2"/>';
      if (isRight) {
        svg += '<polygon points="' + (width - pad + 13) + ',32 ' + (width - pad + 4) + ',27 ' + (width - pad + 4) + ',37" fill="#1d6fd8"/>';
      } else {
        svg += '<polygon points="' + (pad - 13) + ',32 ' + (pad - 4) + ',27 ' + (pad - 4) + ',37" fill="#1d6fd8"/>';
      }
      svg += '<circle cx="' + sx.toFixed(1) + '" cy="32" r="4.8" fill="' + (isClosed ? '#1d6fd8' : '#ffffff') + '" stroke="#1d6fd8" stroke-width="2.2"/>';
    }
    svg += '</svg>';
    return svg;
  }

  var pairs = [
    ['>=', '<'],
    ['>', '<='],
    ['<=', '>'],
    ['<', '>=']
  ];
  var pair = pick(pairs);
  if (Math.random() < 0.5) pair = [pair[1], pair[0]];

  var multFirst = Math.random() < 0.5;
  var negFirst = Math.random() < 0.5;

  var specs = [
    { isMult: multFirst, isNeg: negFirst, sym: pair[0], label: 'A)' },
    { isMult: !multFirst, isNeg: !negFirst, sym: pair[1], label: 'B)' }
  ];

  var problems = specs.map(function(sp) {
    var sol = randInt(-14, 14);
    var origTex = '';
    var step1 = '';
    var step2 = '';
    var step3 = '';
    var finalSym = sp.isNeg ? flipSym(sp.sym) : sp.sym;
    var ts = texSym(sp.sym);
    var fs = texSym(finalSym);

    if (sp.isMult) {
      var mode = randInt(1, 2);
      if (mode === 1) {
        // a(x + b) + c + d [sym] rhs  (4 steps: distribute, combine constants, undo constant, divide by a)
        var a = sp.isNeg ? -pick([2, 3, 4]) : pick([2, 3, 4]);
        var b = pick([-5, -4, -3, -2, 2, 3, 4, 5]);
        var c = pick([-8, -7, -6, -5, -4, 4, 5, 6, 7, 8]);
        var d = pick([-9, -8, -7, -5, -4, 4, 5, 7, 8, 9]);
        while (c + d === 0) {
          d = pick([-9, -8, -7, -5, -4, 4, 5, 7, 8, 9]);
        }
        var ab = a * b;
        var comb = ab + c + d;
        var rhs = a * sol + comb;

        origTex = a + '(x ' + fmtSign(b) + ') ' + fmtSign(c) + ' ' + fmtSign(d) + ' ' + ts + ' ' + rhs;
        step1 = a + 'x ' + fmtSign(ab) + ' ' + fmtSign(c) + ' ' + fmtSign(d) + ' ' + ts + ' ' + rhs;
        step2 = a + 'x ' + fmtSign(comb) + ' ' + ts + ' ' + rhs;
        step3 = a + 'x ' + ts + ' ' + (rhs - comb);
      } else {
        // p(x + b) + q [sym] r x + rhs  (4 steps: distribute, subtract rx, undo constant, divide by (p-r))
        var diff = sp.isNeg ? -pick([2, 3, 4]) : pick([2, 3, 4]);
        var r = pick([2, 3, 4]);
        var p = r + diff;
        if (p === 0 || p === 1 || p === -1) {
          r = 5;
          p = r + diff;
        }
        var b = pick([-4, -3, -2, 2, 3, 4]);
        var q = pick([-7, -6, -5, -4, 4, 5, 6, 7]);
        var pb = p * b;
        var comb = pb + q;
        var rhs = diff * sol + comb;

        origTex = p + '(x ' + fmtSign(b) + ') ' + fmtSign(q) + ' ' + ts + ' ' + r + 'x ' + fmtSign(rhs);
        step1 = p + 'x ' + fmtSign(pb) + ' ' + fmtSign(q) + ' ' + ts + ' ' + r + 'x ' + fmtSign(rhs);
        step2 = p + 'x ' + fmtSign(comb) + ' ' + ts + ' ' + r + 'x ' + fmtSign(rhs);
        step3 = diff + 'x ' + fmtSign(comb) + ' ' + ts + ' ' + rhs;
        // Adjust to 4 clean visible steps before final answer
        var step3b = diff + 'x ' + ts + ' ' + (rhs - comb);
        step3 = step3 + ' \\;\\Rightarrow\\; ' + step3b;
      }
    } else {
      // Division multi-step:
      // (x + b)/d + c + e [sym] rhs  (4 steps: combine c+e, undo constant, multiply by d, undo b)
      var d = sp.isNeg ? -pick([2, 3, 4]) : pick([2, 3, 4]);
      var b = pick([-6, -5, -4, -3, -2, 2, 3, 4, 5, 6]);
      var k = randInt(-5, 5);
      while (k === 0) k = randInt(-5, 5);
      sol = d * k - b;
      if (sol < -15 || sol > 15) {
        k = k > 0 ? 2 : -2;
        sol = d * k - b;
      }
      var c = pick([-7, -6, -5, -4, 4, 5, 6, 7]);
      var e = pick([-8, -7, -5, -4, 4, 5, 7, 8]);
      while (c + e === 0) {
        e = pick([-8, -7, -5, -4, 4, 5, 7, 8]);
      }
      var ce = c + e;
      var rhs = k + ce;
      var fracStr = sp.isNeg
        ? '-\\frac{x ' + fmtSign(b) + '}{' + Math.abs(d) + '}'
        : '\\frac{x ' + fmtSign(b) + '}{' + d + '}';

      origTex = fracStr + ' ' + fmtSign(c) + ' ' + fmtSign(e) + ' ' + ts + ' ' + rhs;
      step1 = fracStr + ' ' + fmtSign(ce) + ' ' + ts + ' ' + rhs;
      step2 = fracStr + ' ' + ts + ' ' + k;
      step3 = 'x ' + fmtSign(b) + ' ' + fs + ' ' + (k * d);
    }

    var finalTex = 'x ' + fs + ' ' + sol;
    var finalHtml = 'x ' + htmlSym(finalSym) + ' ' + sol;

    var qCard = '<div style="flex:1;min-width:290px;border:1px solid #d0d7de;border-radius:8px;padding:12px 14px;background:#ffffff;box-sizing:border-box;">' +
      '<div style="font-weight:bold;font-size:14px;color:#202b36;margin-bottom:6px;">' + sp.label + '</div>' +
      '<div style="font-size:15px;text-align:center;margin:6px 0 8px 0;">\\( ' + origTex + ' \\)</div>' +
      buildNumberLine(sol, finalSym, false) +
    '</div>';

    var aCard = '<div style="flex:1;min-width:290px;border:1px solid #d0d7de;border-radius:8px;padding:12px 14px;background:#f8fafc;box-sizing:border-box;">' +
      '<div style="font-weight:bold;font-size:14px;color:#202b36;margin-bottom:6px;">' + sp.label + ' Solution: <b>' + finalHtml + '</b></div>' +
      '<div style="font-size:13px;line-height:1.7;color:#202b36;margin-bottom:6px;">' +
        '<b>Step 1:</b> \\( ' + step1 + ' \\)<br>' +
        '<b>Step 2:</b> \\( ' + step2 + ' \\)<br>' +
        '<b>Step 3:</b> \\( ' + step3 + ' \\)<br>' +
        '<b>Step 4:</b> \\( ' + finalTex + ' \\)' +
      '</div>' +
      buildNumberLine(sol, finalSym, true) +
    '</div>';

    return { qCard: qCard, aCard: aCard };
  });

  var qHtml = '<div style="display:flex;flex-wrap:wrap;gap:14px;margin-top:8px;">' + problems[0].qCard + problems[1].qCard + '</div>';
  var aHtml = '<div style="display:flex;flex-wrap:wrap;gap:14px;">' + problems[0].aCard + problems[1].aCard + '</div>';

  return { question_html: qHtml, answer_html: aHtml };
})()

data.formula:
(function(){
  function randInt(min, max) {
    return min + Math.floor(Math.random() * (max - min + 1));
  }
  function pick(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
  }
  function signStr(n) {
    return n >= 0 ? ' + ' + n : ' - ' + Math.abs(n);
  }
  function termStr(coeff, isFirst) {
    var absC = Math.abs(coeff);
    var base = (absC === 1 ? '' : String(absC)) + '<i>x</i>';
    if (isFirst) {
      return (coeff < 0 ? '-' : '') + base;
    }
    return (coeff >= 0 ? ' + ' : ' - ') + base;
  }
  function flipSym(sym) {
    if (sym === '>=') return '<=';
    if (sym === '<=') return '>=';
    if (sym === '>') return '<';
    return '>';
  }
  function symHtml(sym) {
    if (sym === '>=') return '&ge;';
    if (sym === '<=') return '&le;';
    if (sym === '>') return '&gt;';
    return '&lt;';
  }
  function fracHtml(numHtml, den) {
    return '<span style="display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;margin:0 4px;line-height:1.15">' +
           '<span style="border-bottom:1.5px solid #202b36;padding:0 5px 2px 5px">' + numHtml + '</span>' +
           '<span style="padding:2px 5px 0 5px">' + den + '</span></span>';
  }

  function buildNumberLine(sol, sym) {
    var w = 400, h = 68, pad = 24;
    var span = w - 2 * pad;
    function xPos(val) {
      return pad + ((val + 20) / 40) * span;
    }
    var svg = '<svg viewBox="0 0 ' + w + ' ' + h + '" style="width:100%;max-width:400px;height:auto;display:block;margin:8px auto 0 auto;font-family:Arial,sans-serif">';
    svg += '<line x1="' + (pad - 10) + '" y1="32" x2="' + (w - pad + 10) + '" y2="32" stroke="#202b36" stroke-width="2"/>';
    svg += '<polygon points="' + (pad - 14) + ',32 ' + (pad - 6) + ',27 ' + (pad - 6) + ',37" fill="#202b36"/>';
    svg += '<polygon points="' + (w - pad + 14) + ',32 ' + (w - pad + 6) + ',27 ' + (w - pad + 6) + ',37" fill="#202b36"/>';
    for (var i = -20; i <= 20; i++) {
      var x = xPos(i);
      var isMajor = (i % 5 === 0);
      var tickTop = isMajor ? 25 : 28;
      var tickBot = isMajor ? 39 : 36;
      svg += '<line x1="' + x.toFixed(1) + '" y1="' + tickTop + '" x2="' + x.toFixed(1) + '" y2="' + tickBot + '" stroke="#202b36" stroke-width="' + (isMajor ? '1.5' : '1') + '"/>';
      if (isMajor) {
        svg += '<text x="' + x.toFixed(1) + '" y="54" font-size="11" text-anchor="middle" fill="#202b36">' + i + '</text>';
      }
    }
    if (sol !== null) {
      var sx = xPos(sol);
      var isClosed = (sym === '>=' || sym === '<=');
      var isRight = (sym === '>=' || sym === '>');
      if (isRight) {
        svg += '<line x1="' + sx.toFixed(1) + '" y1="32" x2="' + (w - pad + 10) + '" y2="32" stroke="#0b66c3" stroke-width="4.5"/>';
        svg += '<polygon points="' + (w - pad + 15) + ',32 ' + (w - pad + 5) + ',26 ' + (w - pad + 5) + ',38" fill="#0b66c3"/>';
      } else {
        svg += '<line x1="' + (pad - 10) + '" y1="32" x2="' + sx.toFixed(1) + '" y2="32" stroke="#0b66c3" stroke-width="4.5"/>';
        svg += '<polygon points="' + (pad - 15) + ',32 ' + (pad - 5) + ',26 ' + (pad - 5) + ',38" fill="#0b66c3"/>';
      }
      svg += '<circle cx="' + sx.toFixed(1) + '" cy="32" r="5.5" fill="' + (isClosed ? '#0b66c3' : '#ffffff') + '" stroke="#0b66c3" stroke-width="2.5"/>';
    }
    svg += '</svg>';
    return svg;
  }

  var pairs = [
    ['>=', '<'],
    ['>', '<='],
    ['<=', '>'],
    ['<', '>=']
  ];
  var chosenPair = pick(pairs);
  var multIsFirst = Math.random() < 0.5;
  var negIsFirst = Math.random() < 0.5;
  var splitIsFirst = Math.random() < 0.5;

  function makeMultProblem(sym, needFlip, isSplit) {
    var sol, a1, a2, a3, b, c1, c2, rhs, netCoeff, remConst, step1, step2, step3, step4, finalSym, eqHtml;
    if (!isSplit) {
      while (true) {
        sol = randInt(-14, 14);
        a1 = pick([-4, -3, -2, 2, 3, 4]);
        a2 = pick([-4, -3, -2, 2, 3, 4]);
        a3 = pick([-5, -4, -3, -2, 2, 3, 4, 5]);
        netCoeff = a1 + a2 + a3;
        if (needFlip && netCoeff >= -1) continue;
        if (!needFlip && netCoeff <= 1) continue;
        b = pick([-5, -4, -3, -2, 2, 3, 4, 5]);
        var d = pick([-5, -4, -3, -2, 2, 3, 4, 5]);
        c1 = pick([-9, -8, -7, -6, -5, -4, -3, -2, 2, 3, 4, 5, 6, 7, 8, 9]);
        remConst = a1 * b + a2 * d + c1;
        rhs = netCoeff * sol + remConst;
        if (Math.abs(rhs) <= 45) break;
      }
      finalSym = needFlip ? flipSym(sym) : sym;
      eqHtml = a1 + '(<i>x</i>' + signStr(b) + ')' + signStr(a2) + '(<i>x</i>' + signStr(d) + ')' + termStr(a3, false) + signStr(c1) + ' ' + symHtml(sym) + ' ' + rhs;
      step1 = termStr(a1, true) + signStr(a1 * b) + termStr(a2, false) + signStr(a2 * d) + termStr(a3, false) + signStr(c1) + ' ' + symHtml(sym) + ' ' + rhs + '  (Distribute)';
      step2 = termStr(netCoeff, true) + signStr(remConst) + ' ' + symHtml(sym) + ' ' + rhs + '  (Combine like terms)';
      step3 = termStr(netCoeff, true) + ' ' + symHtml(sym) + ' ' + (rhs - remConst) + '  (' + (remConst >= 0 ? 'Subtract ' + remConst : 'Add ' + Math.abs(remConst)) + ')';
      step4 = 'Divide by ' + netCoeff + (needFlip ? ' (flip inequality sign)' : '');
    } else {
      var oneOnLeft = Math.random() < 0.5;
      while (true) {
        sol = randInt(-14, 14);
        a1 = pick([-4, -3, -2, 2, 3, 4]);
        a2 = pick([-4, -3, -2, 2, 3, 4]);
        a3 = pick([-5, -4, -3, -2, 2, 3, 4, 5]);
        var leftCoeff = oneOnLeft ? a3 : (a1 + a2);
        var rightCoeff = oneOnLeft ? (a1 + a2) : a3;
        netCoeff = leftCoeff - rightCoeff;
        if (needFlip && netCoeff >= -1) continue;
        if (!needFlip && netCoeff <= 1) continue;
        b = pick([-5, -4, -3, -2, 2, 3, 4, 5]);
        c1 = pick([-9, -8, -7, -6, -5, -4, -3, -2, 2, 3, 4, 5, 6, 7, 8, 9]);
        c2 = pick([-9, -8, -7, -6, -5, -4, -3, -2, 2, 3, 4, 5, 6, 7, 8, 9]);
        if (oneOnLeft) {
          var rightConst = a1 * b + c2;
          rhs = netCoeff * sol + rightConst - c1;
          // wait: left is a3*x + c1, right is a1(x+b) + a2*x + c2
          // At x = sol: a3*sol + c1 == (a1+a2)*sol + a1*b + c2
          // So c2 = a3*sol + c1 - (a1+a2)*sol - a1*b = netCoeff*sol + c1 - a1*b
          c2 = netCoeff * sol + c1 - a1 * b;
          if (Math.abs(c2) > 45) continue;
          finalSym = needFlip ? flipSym(sym) : sym;
          eqHtml = termStr(a3, true) + signStr(c1) + ' ' + symHtml(sym) + ' ' + a1 + '(<i>x</i>' + signStr(b) + ')' + termStr(a2, false) + signStr(c2);
          step1 = termStr(a3, true) + signStr(c1) + ' ' + symHtml(sym) + ' ' + termStr(a1, true) + signStr(a1 * b) + termStr(a2, false) + signStr(c2) + '  (Distribute)';
          step2 = termStr(a3, true) + signStr(c1) + ' ' + symHtml(sym) + ' ' + termStr(rightCoeff, true) + signStr(a1 * b + c2) + '  (Combine like terms on right)';
          step3 = termStr(netCoeff, true) + signStr(c1) + ' ' + symHtml(sym) + ' ' + (a1 * b + c2) + '  (' + (rightCoeff >= 0 ? 'Subtract ' + rightCoeff + '<i>x</i>' : 'Add ' + Math.abs(rightCoeff) + '<i>x</i>') + ')';
          step4 = termStr(netCoeff, true) + ' ' + symHtml(sym) + ' ' + (a1 * b + c2 - c1) + '  (' + (c1 >= 0 ? 'Subtract ' + c1 : 'Add ' + Math.abs(c1)) + ')';
          break;
        } else {
          // left is a1(x+b) + a2*x + c1, right is a3*x + c2
          // (a1+a2)*sol + a1*b + c1 == a3*sol + c2 => c2 = netCoeff*sol + a1*b + c1
          c2 = netCoeff * sol + a1 * b + c1;
          if (Math.abs(c2) > 45) continue;
          finalSym = needFlip ? flipSym(sym) : sym;
          eqHtml = a1 + '(<i>x</i>' + signStr(b) + ')' + termStr(a2, false) + signStr(c1) + ' ' + symHtml(sym) + ' ' + termStr(a3, true) + signStr(c2);
          step1 = termStr(a1, true) + signStr(a1 * b) + termStr(a2, false) + signStr(c1) + ' ' + symHtml(sym) + ' ' + termStr(a3, true) + signStr(c2) + '  (Distribute)';
          step2 = termStr(leftCoeff, true) + signStr(a1 * b + c1) + ' ' + symHtml(sym) + ' ' + termStr(a3, true) + signStr(c2) + '  (Combine like terms on left)';
          step3 = termStr(netCoeff, true) + signStr(a1 * b + c1) + ' ' + symHtml(sym) + ' ' + c2 + '  (' + (a3 >= 0 ? 'Subtract ' + a3 + '<i>x</i>' : 'Add ' + Math.abs(a3) + '<i>x</i>') + ')';
          step4 = termStr(netCoeff, true) + ' ' + symHtml(sym) + ' ' + (c2 - a1 * b - c1) + '  (' + ((a1 * b + c1) >= 0 ? 'Subtract ' + (a1 * b + c1) : 'Add ' + Math.abs(a1 * b + c1)) + ')';
          break;
        }
      }
    }
    return {
      eqHtml: eqHtml,
      step1: step1,
      step2: step2,
      step3: step3,
      step4: step4,
      solHtml: '<i>x</i> ' + symHtml(finalSym) + ' ' + sol,
      blankLine: buildNumberLine(null, sym),
      solvedLine: buildNumberLine(sol, finalSym)
    };
  }

  function makeDivProblem(sym, needFlip, isSplit) {
    // Simple multiples for denominators: e.g. base = 2, 3, or 4 -> mults like (2, 4, 6), (2, 4, 8), (3, 6, 9)
    var denSets = [
      [2, 4, 6, 12],
      [2, 4, 8, 8],
      [3, 6, 9, 18],
      [2, 3, 6, 6],
      [3, 6, 12, 12],
      [4, 8, 12, 24]
    ];
    var sol, d1, d2, d3, lcm, m1, m2, m3, s1, s2, s3, b1, b2, c1, c2, netCoeff, remConst, step1, step2, step3, step4, finalSym, eqHtml;

    if (!isSplit) {
      while (true) {
        var ds = pick(denSets);
        var perm = [ds[0], ds[1], ds[2]];
        for (var i = perm.length - 1; i > 0; i--) {
          var j = Math.floor(Math.random() * (i + 1));
          var tmp = perm[i]; perm[i] = perm[j]; perm[j] = tmp;
        }
        d1 = perm[0]; d2 = perm[1]; d3 = perm[2];
        lcm = ds[3];
        m1 = lcm / d1; m2 = lcm / d2; m3 = lcm / d3;
        s1 = pick([-1, 1]);
        s2 = pick([-1, 1]);
        s3 = pick([-1, 1]);
        netCoeff = s1 * m1 + s2 * m2 + s3 * m3;
        if (needFlip && netCoeff >= -1) continue;
        if (!needFlip && netCoeff <= 1) continue;
        sol = randInt(-14, 14);
        b1 = pick([-4, -3, -2, -1, 1, 2, 3, 4]);
        b2 = pick([-4, -3, -2, -1, 1, 2, 3, 4]);
        c1 = pick([-5, -4, -3, -2, -1, 1, 2, 3, 4, 5]);
        remConst = s1 * m1 * b1 + s2 * m2 * b2 + lcm * c1;
        // Total cleared LHS = netCoeff * sol + remConst, must be divisible by lcm so RHS is an integer!
        var totalCleared = netCoeff * sol + remConst;
        if (totalCleared % lcm !== 0) continue;
        var rhs = totalCleared / lcm;
        if (Math.abs(rhs) > 25) continue;

        finalSym = needFlip ? flipSym(sym) : sym;
        var f1 = (s1 < 0 ? '-' : '') + fracHtml('<i>x</i>' + signStr(b1), d1);
        var f2 = (s2 < 0 ? ' - ' : ' + ') + fracHtml('<i>x</i>' + signStr(b2), d2);
        var f3 = (s3 < 0 ? ' - ' : ' + ') + fracHtml('<i>x</i>', d3);
        eqHtml = f1 + f2 + f3 + signStr(c1) + ' ' + symHtml(sym) + ' ' + rhs;

        var cTerm1 = (s1 * m1) + '(<i>x</i>' + signStr(b1) + ')';
        var cTerm2 = ((s2 * m2) >= 0 ? ' + ' : ' - ') + Math.abs(s2 * m2) + '(<i>x</i>' + signStr(b2) + ')';
        var cTerm3 = termStr(s3 * m3, false);
        step1 = cTerm1 + cTerm2 + cTerm3 + signStr(lcm * c1) + ' ' + symHtml(sym) + ' ' + (rhs * lcm) + '  (Multiply by LCD = ' + lcm + ')';
        step2 = termStr(s1 * m1, true) + signStr(s1 * m1 * b1) + termStr(s2 * m2, false) + signStr(s2 * m2 * b2) + termStr(s3 * m3, false) + signStr(lcm * c1) + ' ' + symHtml(sym) + ' ' + (rhs * lcm) + '  (Distribute)';
        step3 = termStr(netCoeff, true) + signStr(remConst) + ' ' + symHtml(sym) + ' ' + (rhs * lcm) + '  (Combine like terms)';
        step4 = termStr(netCoeff, true) + ' ' + symHtml(sym) + ' ' + (rhs * lcm - remConst) + '  (' + (remConst >= 0 ? 'Subtract ' + remConst : 'Add ' + Math.abs(remConst)) + ')';
        break;
      }
    } else {
      var oneOnLeft = Math.random() < 0.5;
      while (true) {
        var ds = pick(denSets);
        var perm = [ds[0], ds[1], ds[2]];
        for (var i = perm.length - 1; i > 0; i--) {
          var j = Math.floor(Math.random() * (i + 1));
          var tmp = perm[i]; perm[i] = perm[j]; perm[j] = tmp;
        }
        d1 = perm[0]; d2 = perm[1]; d3 = perm[2];
        lcm = ds[3];
        m1 = lcm / d1; m2 = lcm / d2; m3 = lcm / d3;
        s1 = pick([-1, 1]);
        s2 = pick([-1, 1]);
        s3 = pick([-1, 1]);
        var twoCoeff = s1 * m1 + s2 * m2;
        var oneCoeff = s3 * m3;
        netCoeff = oneOnLeft ? (oneCoeff - twoCoeff) : (twoCoeff - oneCoeff);
        if (needFlip && netCoeff >= -1) continue;
        if (!needFlip && netCoeff <= 1) continue;
        sol = randInt(-14, 14);
        b1 = pick([-4, -3, -2, -1, 1, 2, 3, 4]);
        c1 = pick([-5, -4, -3, -2, -1, 1, 2, 3, 4, 5]);
        // Need cleared constants difference divisible by lcm so c2 is an integer
        if (oneOnLeft) {
          // Cleared LHS: oneCoeff*x + lcm*c1; Cleared RHS: twoCoeff*x + s1*m1*b1 + lcm*c2
          // lcm*(c2 - c1) = netCoeff*sol - s1*m1*b1
          var numDiff = netCoeff * sol - s1 * m1 * b1;
          if (numDiff % lcm !== 0) continue;
          c2 = c1 + (numDiff / lcm);
          if (Math.abs(c2) > 25) continue;

          finalSym = needFlip ? flipSym(sym) : sym;
          var fSingle = (s3 < 0 ? '-' : '') + fracHtml('<i>x</i>', d3);
          var fPair1 = (s1 < 0 ? '-' : '') + fracHtml('<i>x</i>' + signStr(b1), d1);
          var fPair2 = (s2 < 0 ? ' - ' : ' + ') + fracHtml('<i>x</i>', d2);
          eqHtml = fSingle + signStr(c1) + ' ' + symHtml(sym) + ' ' + fPair1 + fPair2 + signStr(c2);

          step1 = termStr(oneCoeff, true) + signStr(lcm * c1) + ' ' + symHtml(sym) + ' ' + (s1 * m1) + '(<i>x</i>' + signStr(b1) + ')' + termStr(s2 * m2, false) + signStr(lcm * c2) + '  (Multiply by LCD = ' + lcm + ')';
          step2 = termStr(oneCoeff, true) + signStr(lcm * c1) + ' ' + symHtml(sym) + ' ' + termStr(twoCoeff, true) + signStr(s1 * m1 * b1 + lcm * c2) + '  (Distribute & combine on right)';
          step3 = termStr(netCoeff, true) + signStr(lcm * c1) + ' ' + symHtml(sym) + ' ' + (s1 * m1 * b1 + lcm * c2) + '  (' + (twoCoeff >= 0 ? 'Subtract ' + twoCoeff + '<i>x</i>' : 'Add ' + Math.abs(twoCoeff) + '<i>x</i>') + ')';
          step4 = termStr(netCoeff, true) + ' ' + symHtml(sym) + ' ' + (s1 * m1 * b1 + lcm * c2 - lcm * c1) + '  (' + ((lcm * c1) >= 0 ? 'Subtract ' + (lcm * c1) : 'Add ' + Math.abs(lcm * c1)) + ')';
          break;
        } else {
          // Cleared LHS: twoCoeff*x + s1*m1*b1 + lcm*c1; Cleared RHS: oneCoeff*x + lcm*c2
          // lcm*(c2 - c1) = netCoeff*sol + s1*m1*b1
          var numDiff = netCoeff * sol + s1 * m1 * b1;
          if (numDiff % lcm !== 0) continue;
          c2 = c1 + (numDiff / lcm);
          if (Math.abs(c2) > 25) continue;

          finalSym = needFlip ? flipSym(sym) : sym;
          var fPair1 = (s1 < 0 ? '-' : '') + fracHtml('<i>x</i>' + signStr(b1), d1);
          var fPair2 = (s2 < 0 ? ' - ' : ' + ') + fracHtml('<i>x</i>', d2);
          var fSingle = (s3 < 0 ? '-' : '') + fracHtml('<i>x</i>', d3);
          eqHtml = fPair1 + fPair2 + signStr(c1) + ' ' + symHtml(sym) + ' ' + fSingle + signStr(c2);

          step1 = (s1 * m1) + '(<i>x</i>' + signStr(b1) + ')' + termStr(s2 * m2, false) + signStr(lcm * c1) + ' ' + symHtml(sym) + ' ' + termStr(oneCoeff, true) + signStr(lcm * c2) + '  (Multiply by LCD = ' + lcm + ')';
          step2 = termStr(twoCoeff, true) + signStr(s1 * m1 * b1 + lcm * c1) + ' ' + symHtml(sym) + ' ' + termStr(oneCoeff, true) + signStr(lcm * c2) + '  (Distribute & combine on left)';
          step3 = termStr(netCoeff, true) + signStr(s1 * m1 * b1 + lcm * c1) + ' ' + symHtml(sym) + ' ' + (lcm * c2) + '  (' + (oneCoeff >= 0 ? 'Subtract ' + oneCoeff + '<i>x</i>' : 'Add ' + Math.abs(oneCoeff) + '<i>x</i>') + ')';
          step4 = termStr(netCoeff, true) + ' ' + symHtml(sym) + ' ' + (lcm * c2 - s1 * m1 * b1 - lcm * c1) + '  (' + ((s1 * m1 * b1 + lcm * c1) >= 0 ? 'Subtract ' + (s1 * m1 * b1 + lcm * c1) : 'Add ' + Math.abs(s1 * m1 * b1 + lcm * c1)) + ')';
          break;
        }
      }
    }
    return {
      eqHtml: eqHtml,
      step1: step1,
      step2: step2,
      step3: step3,
      step4: step4,
      solHtml: '<i>x</i> ' + symHtml(finalSym) + ' ' + sol,
      blankLine: buildNumberLine(null, sym),
      solvedLine: buildNumberLine(sol, finalSym)
    };
  }

  var probA = multIsFirst
    ? makeMultProblem(chosenPair[0], negIsFirst, splitIsFirst)
    : makeDivProblem(chosenPair[0], negIsFirst, splitIsFirst);

  var probB = multIsFirst
    ? makeDivProblem(chosenPair[1], !negIsFirst, !splitIsFirst)
    : makeMultProblem(chosenPair[1], !negIsFirst, !splitIsFirst);

  function renderCard(label, p, isAnswer) {
    var boxStyle = 'flex:1;min-width:300px;border:1.5px solid #cbd5e1;border-radius:8px;padding:12px 14px;background:#ffffff;box-sizing:border-box;';
    var headerStyle = 'font-weight:bold;font-size:15px;color:#1e293b;margin-bottom:8px;display:flex;align-items:center;gap:8px;';
    var eqStyle = 'font-size:16px;font-family:Georgia,serif;color:#0f172a;text-align:center;margin:8px 0 10px 0;';
    if (!isAnswer) {
      return '<div style="' + boxStyle + '">' +
             '<div style="' + headerStyle + '"><span>' + label + ')</span></div>' +
             '<div style="' + eqStyle + '">' + p.eqHtml + '</div>' +
             p.blankLine +
             '</div>';
    }
    var stepsStyle = 'font-size:12.5px;color:#334155;background:#f8fafc;border-left:3px solid #0b66c3;padding:8px 10px;margin:8px 0;line-height:1.55;';
    return '<div style="' + boxStyle + '">' +
           '<div style="' + headerStyle + '"><span>' + label + ')</span> <span style="color:#0b66c3">' + p.solHtml + '</span></div>' +
           '<div style="' + eqStyle + '">' + p.eqHtml + '</div>' +
           '<div style="' + stepsStyle + '">' +
           '<div><b>Step 1:</b> ' + p.step1 + '</div>' +
           '<div><b>Step 2:</b> ' + p.step2 + '</div>' +
           '<div><b>Step 3:</b> ' + p.step3 + '</div>' +
           '<div><b>Step 4:</b> ' + p.step4 + '</div>' +
           '<div><b>Solution:</b> ' + p.solHtml + '</div>' +
           '</div>' +
           p.solvedLine +
           '</div>';
  }

  var rowWrap = '<div style="display:flex;flex-wrap:wrap;gap:14px;margin-top:8px;width:100%">';
  return {
    questionHtml: rowWrap + renderCard('A', probA, false) + renderCard('B', probB, false) + '</div>',
    answerHtml: rowWrap + renderCard('A', probA, true) + renderCard('B', probB, true) + '</div>'
  };
})()

pie_sets.formula:
(function(){
  var flavors = [
    {name:'Apple', fill:'#d9822b', crust:'#e6b87d', accent:'#b35c1e'},
    {name:'Cherry', fill:'#b81d38', crust:'#e6b87d', accent:'#800f23'},
    {name:'Blueberry', fill:'#3b4d8c', crust:'#e6b87d', accent:'#232f59'},
    {name:'Pumpkin', fill:'#d96b27', crust:'#e6b87d', accent:'#a64b14'},
    {name:'Key Lime', fill:'#88b04b', crust:'#e2c08d', accent:'#5f8030'},
    {name:'Lemon Meringue', fill:'#f2c94c', crust:'#e6b87d', accent:'#d4a31e'},
    {name:'Pecan', fill:'#7a4424', crust:'#e6b87d', accent:'#4d2812'},
    {name:'Peach', fill:'#e88d4f', crust:'#e6b87d', accent:'#bf682e'}
  ];
  for (var i = flavors.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var t = flavors[i]; flavors[i] = flavors[j]; flavors[j] = t;
  }

  function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }
  function lcm(a, b) { return (a * b) / gcd(a, b); }

  // Candidate pairs of mixed numbers whose sums are close to each other
  // Format: [ [w1, n1, d1], [w2, n2, d2] ]
  // Let's create several rich groups of 3 distinct sets with close totals (all around 3.5 to 4.5 pies)
  var poolGroups = [
    [
      [[1, 3, 4], [2, 1, 6]], // 3 + 9/12 + 2/12 = 3 11/12 (47/12 = 141/36)
      [[2, 1, 3], [1, 1, 2]], // 3 + 2/6 + 3/6 = 3 5/6 (23/6 = 138/36)
      [[1, 5, 6], [2, 1, 9]]  // 3 + 15/18 + 2/18 = 3 17/18 (71/18 = 142/36)
    ],
    [
      [[2, 1, 4], [1, 2, 5]], // 3 + 5/20 + 8/20 = 3 13/20 (73/20 = 219/60)
      [[1, 5, 6], [1, 4, 5]], // 2 + 25/30 + 24/30 = 3 19/30 (109/30 = 218/60)
      [[2, 1, 6], [1, 1, 2]]  // 3 + 1/6 + 3/6 = 3 4/6 = 3 2/3 (11/3 = 220/60)
    ],
    [
      [[1, 2, 3], [2, 1, 8]], // 3 + 16/24 + 3/24 = 3 19/24 (91/24)
      [[2, 1, 4], [1, 1, 2]], // 3 + 1/4 + 2/4 = 3 3/4 (90/24)
      [[1, 5, 8], [2, 1, 6]]  // 3 + 15/24 + 4/24 = 3 19/24 -> change to [1, 7, 12] + [2, 1, 8] = 3 + 14/24 + 3/24 = 3 17/24 (89/24)
    ],
    [
      [[2, 2, 5], [1, 3, 4]], // 3 + 8/20 + 15/20 = 4 3/20 (83/20 = 249/60)
      [[1, 5, 6], [2, 1, 3]], // 3 + 5/6 + 2/6 = 4 1/6 (25/6 = 250/60)
      [[2, 3, 10], [1, 5, 6]] // 3 + 9/30 + 25/30 = 4 4/30 = 4 2/15 (62/15 = 248/60)
    ],
    [
      [[1, 3, 5], [1, 3, 4]], // 2 + 12/20 + 15/20 = 3 7/20 (67/20 = 201/60)
      [[2, 1, 6], [1, 1, 5]], // 3 + 5/30 + 6/30 = 3 11/30 (101/30 = 202/60)
      [[1, 2, 3], [1, 2, 3]]  // 2 + 4/3 = 3 1/3 (10/3 = 200/60) -> let's use [[1, 3, 4], [1, 7, 12]] = 3 1/3
    ]
  ];

  // Ensure group 2 & 4 have distinct flavors/fractions
  poolGroups[2][2] = [[1, 7, 12], [2, 1, 8]]; // 3 17/24
  poolGroups[4][2] = [[1, 3, 4], [1, 7, 12]]; // 3 1/3

  var chosen = poolGroups[Math.floor(Math.random() * poolGroups.length)];
  var labels = ['Set A', 'Set B', 'Set C'];
  // Shuffle labels assignment so least isn't always in the same spot
  var indices = [0, 1, 2];
  for (var k = indices.length - 1; k > 0; k--) {
    var r = Math.floor(Math.random() * (k + 1));
    var tmp = indices[k]; indices[k] = indices[r]; indices[r] = tmp;
  }

  var fIdx = 0;
  var sets = indices.map(function(origIdx, sIdx) {
    var pair = chosen[origIdx];
    var items = pair.map(function(m) {
      var w = m[0], n = m[1], d = m[2];
      var fl = flavors[fIdx % flavors.length];
      fIdx++;
      return {
        whole: w,
        num: n,
        den: d,
        flavor: fl,
        improper_num: w * d + n
      };
    });

    // Compute exact sum of the two mixed numbers
    var a = items[0], b = items[1];
    var commonD = lcm(a.den, b.den);
    var m1 = commonD / a.den;
    var m2 = commonD / b.den;
    var eqNum1 = a.num * m1;
    var eqNum2 = b.num * m2;
    var fracSumNum = eqNum1 + eqNum2;
    var wholeSum = a.whole + b.whole + Math.floor(fracSumNum / commonD);
    var remNum = fracSumNum % commonD;
    var g = gcd(remNum, commonD);
    var simpNum = remNum / g;
    var simpDen = commonD / g;
    var totalImproperNum = wholeSum * simpDen + simpNum;

    return {
      label: labels[sIdx],
      items: items,
      common_den: commonD,
      eq_num1: eqNum1,
      eq_num2: eqNum2,
      frac_sum_num: fracSumNum,
      whole_sum: wholeSum,
      simp_num: simpNum,
      simp_den: simpDen,
      imp_num: totalImproperNum,
      imp_den: simpDen,
      decimal: totalImproperNum / simpDen
    };
  });

  // Find overall LCD across all 3 sets for final comparison
  var overallLCD = lcm(sets[0].imp_den, lcm(sets[1].imp_den, sets[2].imp_den));
  sets.forEach(function(s) {
    s.comp_num = s.imp_num * (overallLCD / s.imp_den);
    s.overall_lcd = overallLCD;
  });

  return sets;
})()

pie_graphic.formula:
(function(){
  function renderPieStack(item) {
    var w = item.whole;
    var n = item.num;
    var d = item.den;
    var fl = item.flavor;
    var frac = n / d;

    // SVG dimensions: allow room in upper-left for 1 or 2 full pies peeking out behind the front pie
    var svgW = 165;
    var svgH = 148;
    var r = 48;
    // Front pie center shifted down-right so background pies peek out cleanly at top-left
    var cx = 96;
    var cy = 88;

    var bgPies = '';
    // Draw background full pies from furthest back to closest
    for (var i = w; i >= 1; i--) {
      var offset = i * 18;
      var bx = cx - offset;
      var by = cy - offset * 0.85;
      bgPies += '<g>' +
        '<circle cx="' + bx + '" cy="' + (by + 3) + '" r="' + (r + 3) + '" fill="rgba(0,0,0,0.12)" />' +
        '<circle cx="' + bx + '" cy="' + by + '" r="' + (r + 3) + '" fill="' + fl.crust + '" stroke="#7a5230" stroke-width="1.5" />' +
        '<circle cx="' + bx + '" cy="' + by + '" r="' + (r - 2) + '" fill="' + fl.fill + '" stroke="' + fl.accent + '" stroke-width="1" />' +
        '<circle cx="' + bx + '" cy="' + by + '" r="' + (r - 8) + '" fill="none" stroke="rgba(255,255,255,0.22)" stroke-width="1.5" stroke-dasharray="4,4" />' +
      '</g>';
    }

    // Front fractional pie
    var startAngle = -Math.PI / 2;
    var endAngle = startAngle + frac * 2 * Math.PI;
    var x1 = cx + r * Math.cos(startAngle);
    var y1 = cy + r * Math.sin(startAngle);
    var x2 = cx + r * Math.cos(endAngle);
    var y2 = cy + r * Math.sin(endAngle);
    var largeArc = frac > 0.5 ? 1 : 0;

    var cr = r + 3;
    var cx1 = cx + cr * Math.cos(startAngle);
    var cy1 = cy + cr * Math.sin(startAngle);
    var cx2 = cx + cr * Math.cos(endAngle);
    var cy2 = cy + cr * Math.sin(endAngle);

    var frontPie = '<g>' +
      // Empty pan circle outline for missing slice reference
      '<circle cx="' + cx + '" cy="' + cy + '" r="' + cr + '" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1.5" stroke-dasharray="3,3" />' +
      // Crust wedge
      '<path d="M ' + cx + ' ' + cy + ' L ' + cx1.toFixed(2) + ' ' + cy1.toFixed(2) + ' A ' + cr + ' ' + cr + ' 0 ' + largeArc + ' 1 ' + cx2.toFixed(2) + ' ' + cy2.toFixed(2) + ' Z" fill="' + fl.crust + '" stroke="#7a5230" stroke-width="1.5" />' +
      // Filling wedge
      '<path d="M ' + cx + ' ' + cy + ' L ' + x1.toFixed(2) + ' ' + y1.toFixed(2) + ' A ' + r + ' ' + r + ' 0 ' + largeArc + ' 1 ' + x2.toFixed(2) + ' ' + y2.toFixed(2) + ' Z" fill="' + fl.fill + '" stroke="' + fl.accent + '" stroke-width="1.2" />';

    // Slice divider lines on front pie for visual clarity
    for (var s = 1; s < d; s++) {
      if (s < n) {
        var ang = startAngle + (s / d) * 2 * Math.PI;
        var lx = cx + (r - 1) * Math.cos(ang);
        var ly = cy + (r - 1) * Math.sin(ang);
        frontPie += '<line x1="' + cx + '" y1="' + cy + '" x2="' + lx.toFixed(2) + '" y2="' + ly.toFixed(2) + '" stroke="rgba(255,255,255,0.28)" stroke-width="1" />';
      }
    }

    // Mixed number badge prominently placed on the front pie
    var badgeX = cx;
    var badgeY = cy + 6;
    frontPie += '<g>' +
      '<rect x="' + (badgeX - 30) + '" y="' + (badgeY - 21) + '" width="60" height="32" rx="6" fill="rgba(255,255,255,0.94)" stroke="#202b36" stroke-width="1.5" />' +
      // Whole number on left of badge
      '<text x="' + (badgeX - 12) + '" y="' + (badgeY + 1) + '" text-anchor="middle" font-family="Arial,sans-serif" font-size="18" font-weight="bold" fill="#202b36">' + w + '</text>' +
      // Numerator
      '<text x="' + (badgeX + 11) + '" y="' + (badgeY - 7) + '" text-anchor="middle" font-family="Arial,sans-serif" font-size="11" font-weight="bold" fill="#202b36">' + n + '</text>' +
      // Fraction bar
      '<line x1="' + (badgeX + 2) + '" y1="' + (badgeY - 4) + '" x2="' + (badgeX + 20) + '" y2="' + (badgeY - 4) + '" stroke="#202b36" stroke-width="1.5" />' +
      // Denominator
      '<text x="' + (badgeX + 11) + '" y="' + (badgeY + 8) + '" text-anchor="middle" font-family="Arial,sans-serif" font-size="11" font-weight="bold" fill="#202b36">' + d + '</text>' +
    '</g></g>';

    return '<div style="display:flex;flex-direction:column;align-items:center">' +
      '<svg width="' + svgW + '" height="' + svgH + '" viewBox="0 0 ' + svgW + ' ' + svgH + '">' + bgPies + frontPie + '</svg>' +
      '<div style="font-size:11px;color:#475569;font-weight:bold;margin-top:2px">' + fl.name + ' (' + w + ' ' + n + '/' + d + ')</div>' +
    '</div>';
  }

  var cards = pie_sets.map(function(s) {
    return '<div style="flex:1;min-width:250px;border:1.5px solid #cbd5e1;border-radius:8px;background:#f8fafc;padding:10px 8px;text-align:center">' +
      '<div style="font-weight:bold;font-size:14px;color:#1e293b;background:#e2e8f0;border-radius:4px;padding:4px 0;margin-bottom:8px">' + s.label + '</div>' +
      '<div style="display:flex;justify-content:center;align-items:center;gap:4px">' +
        renderPieStack(s.items[0]) +
        '<div style="font-size:20px;font-weight:bold;color:#475569;padding:0 2px">+</div>' +
        renderPieStack(s.items[1]) +
      '</div>' +
    '</div>';
  }).join('');

  return '<div style="display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;align-items:stretch;font-family:Arial,sans-serif;margin-top:10px">' + cards + '</div>';
})()

solution_steps.formula:
(function(){
  function fmtMixed(w, n, d) {
    if (n === 0) return '<b>' + w + '</b>';
    return '<b>' + w + ' ' + n + '/' + d + '</b>';
  }

  var step1Rows = pie_sets.map(function(s) {
    var a = s.items[0], b = s.items[1];
    var wholeInitial = a.whole + b.whole;
    var improperNote = '';
    if (s.frac_sum_num >= s.common_den) {
      var extraW = Math.floor(s.frac_sum_num / s.common_den);
      var remN = s.frac_sum_num % s.common_den;
      improperNote = ' = ' + wholeInitial + ' + ' + extraW + (remN > 0 ? ' ' + remN + '/' + s.common_den : '');
    }
    var simplifyNote = '';
    if (s.simp_den !== s.common_den && s.simp_num !== 0) {
      simplifyNote = ' = ' + fmtMixed(s.whole_sum, s.simp_num, s.simp_den);
    } else {
      simplifyNote = ' = ' + fmtMixed(s.whole_sum, s.simp_num, s.simp_den);
    }

    return '<li style="margin-bottom:8px"><b>' + s.label + ':</b> ' +
      a.whole + ' ' + a.num + '/' + a.den + ' + ' + b.whole + ' ' + b.num + '/' + b.den +
      '<br><span style="color:#475569">Add whole numbers and convert fractions to common denominator (' + s.common_den + '):</span> ' +
      '(' + a.whole + ' + ' + b.whole + ') + (' + s.eq_num1 + '/' + s.common_den + ' + ' + s.eq_num2 + '/' + s.common_den + ') = ' +
      wholeInitial + ' + ' + s.frac_sum_num + '/' + s.common_den + improperNote + simplifyNote +
    '</li>';
  }).join('');

  var lcd = pie_sets[0].overall_lcd;
  var step2Rows = pie_sets.map(function(s) {
    var wholeComp = Math.floor(s.comp_num / lcd);
    var remComp = s.comp_num % lcd;
    return '<li><b>' + s.label + ':</b> ' + s.whole_sum + ' ' + s.simp_num + '/' + s.simp_den +
      ' = <b>' + wholeComp + ' ' + remComp + '/' + lcd + '</b> (' + s.comp_num + '/' + lcd + ' pies)</li>';
  }).join('');

  // Find the set with the least total
  var sorted = pie_sets.slice().sort(function(x, y) { return x.comp_num - y.comp_num; });
  var least = sorted[0];

  return '<div style="font-family:Arial,sans-serif;font-size:13px;color:#202b36;line-height:1.5">' +
    '<div style="font-weight:bold;font-size:14px;margin-bottom:6px">Step 1: Add the mixed numbers in each set</div>' +
    '<ul style="margin-top:0;padding-left:20px">' + step1Rows + '</ul>' +
    '<div style="font-weight:bold;font-size:14px;margin-top:10px;margin-bottom:6px">Step 2: Compare the totals using a common denominator (' + lcd + ')</div>' +
    '<ul style="margin-top:0;padding-left:20px">' + step2Rows + '</ul>' +
    '<div style="margin-top:10px;padding:8px 12px;background:#e8eef3;border-left:4px solid #202b36;border-radius:4px">' +
      '<b>Conclusion:</b> Ordering from least to greatest gives <b>' + sorted[0].label + '</b> (' + sorted[0].comp_num + '/' + lcd + ') &lt; <b>' + sorted[1].label + '</b> (' + sorted[1].comp_num + '/' + lcd + ') &lt; <b>' + sorted[2].label + '</b> (' + sorted[2].comp_num + '/' + lcd + '). ' +
      'Since you want to keep the smallest amount for yourself so your two friends get slightly more, you should choose <b>' + least.label + '</b>.' +
    '</div>' +
  '</div>';
})()

scenario.formula:
(function(){
  function gcd(a, b) {
    a = Math.abs(a); b = Math.abs(b);
    while (b) { var t = b; b = a % b; a = t; }
    return a;
  }
  function lcm(a, b) {
    return (a * b) / gcd(a, b);
  }
  function simplify(n, d) {
    var g = gcd(n, d);
    return { n: n / g, d: d / g };
  }
  function toMixed(n, d) {
    var s = simplify(n, d);
    var w = Math.floor(s.n / s.d);
    var rem = s.n % s.d;
    return { whole: w, n: rem, d: s.d, impN: s.n, impD: s.d };
  }
  function fmtMixedText(m) {
    if (m.whole > 0 && m.n > 0) return m.whole + ' ' + m.n + '/' + m.d;
    if (m.whole > 0) return String(m.whole);
    return m.n + '/' + m.d;
  }
  function fmtMixedHtml(m) {
    if (m.whole > 0 && m.n > 0) {
      return m.whole + '<span style="display:inline-flex;flex-direction:column;vertical-align:middle;font-size:0.78em;line-height:1.05;margin-left:3px;text-align:center"><span style="border-bottom:1.5px solid currentColor;padding:0 2px">' + m.n + '</span><span>' + m.d + '</span></span>';
    }
    if (m.whole > 0) return String(m.whole);
    return '<span style="display:inline-flex;flex-direction:column;vertical-align:middle;font-size:0.85em;line-height:1.05;text-align:center"><span style="border-bottom:1.5px solid currentColor;padding:0 2px">' + m.n + '</span><span>' + m.d + '</span></span>';
  }

  var flavors = [
    { name: 'Cherry', fill: '#b81d24', crust: '#e3b878', rim: '#c9934b', dot: '#7a0c12' },
    { name: 'Blueberry', fill: '#2c3e75', crust: '#e3b878', rim: '#c9934b', dot: '#162247' },
    { name: 'Pumpkin', fill: '#d96b27', crust: '#e6be83', rim: '#c99750', dot: '#b34f12' },
    { name: 'Key Lime', fill: '#8cb83e', crust: '#dec08c', rim: '#bfa065', dot: '#6e9628' },
    { name: 'Lemon Meringue', fill: '#f2c94c', crust: '#e3b878', rim: '#c9934b', dot: '#fff8dc' },
    { name: 'Apple', fill: '#c87d32', crust: '#e5bc7d', rim: '#c7954e', dot: '#9c5b1c' },
    { name: 'Pecan', fill: '#6e3b1e', crust: '#e3b878', rim: '#c9934b', dot: '#47220d' },
    { name: 'Blackberry', fill: '#4a1c40', crust: '#e3b878', rim: '#c9934b', dot: '#2b0d24' }
  ];
  for (var i = flavors.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = flavors[i]; flavors[i] = flavors[j]; flavors[j] = tmp;
  }

  var bases = [
    {
      c1: { w: 1, n: 1, d: 4 }, c2: { w: 1, n: 1, d: 3 },
      b1: { w: 2, n: 1, d: 2 }, b2: { w: 2, n: 3, d: 4 },
      a1: { w: 3, n: 2, d: 3 }, a2: { w: 4, n: 1, d: 4 }
    },
    {
      c1: { w: 1, n: 1, d: 6 }, c2: { w: 1, n: 1, d: 4 },
      b1: { w: 2, n: 1, d: 3 }, b2: { w: 2, n: 2, d: 3 },
      a1: { w: 3, n: 1, d: 2 }, a2: { w: 3, n: 5, d: 6 }
    },
    {
      c1: { w: 1, n: 1, d: 3 }, c2: { w: 1, n: 1, d: 2 },
      b1: { w: 2, n: 3, d: 4 }, b2: { w: 3, n: 1, d: 6 },
      a1: { w: 4, n: 1, d: 3 }, a2: { w: 4, n: 1, d: 4 }
    },
    {
      c1: { w: 1, n: 2, d: 5 }, c2: { w: 1, n: 1, d: 2 },
      b1: { w: 2, n: 4, d: 5 }, b2: { w: 3, n: 1, d: 10 },
      a1: { w: 4, n: 1, d: 5 }, a2: { w: 4, n: 1, d: 2 }
    },
    {
      c1: { w: 1, n: 1, d: 8 }, c2: { w: 1, n: 1, d: 4 },
      b1: { w: 2, n: 1, d: 4 }, b2: { w: 2, n: 3, d: 8 },
      a1: { w: 3, n: 1, d: 2 }, a2: { w: 3, n: 3, d: 8 }
    },
    {
      c1: { w: 1, n: 1, d: 2 }, c2: { w: 1, n: 2, d: 3 },
      b1: { w: 3, n: 1, d: 6 }, b2: { w: 3, n: 1, d: 3 },
      a1: { w: 4, n: 1, d: 2 }, a2: { w: 4, n: 5, d: 6 }
    }
  ];

  var chosen = bases[Math.floor(Math.random() * bases.length)];

  function buildSet(id, label, people, personDesc, p1, p2, f1, f2) {
    var imp1N = p1.w * p1.d + p1.n;
    var imp2N = p2.w * p2.d + p2.n;
    var lcd = lcm(p1.d, p2.d);
    var m1 = lcd / p1.d;
    var m2 = lcd / p2.d;
    var conv1N = p1.n * m1;
    var conv2N = p2.n * m2;
    var sumFracN = conv1N + conv2N;
    var sumWhole = p1.w + p2.w;
    var totalImpN = sumWhole * lcd + sumFracN;
    var totalMixed = toMixed(totalImpN, lcd);

    var perPerson = toMixed(totalMixed.impN, totalMixed.impD * people);

    return {
      id: id,
      label: label,
      people: people,
      personDesc: personDesc,
      items: [
        { whole: p1.w, n: p1.n, d: p1.d, flavor: f1, text: fmtMixedText({ whole: p1.w, n: p1.n, d: p1.d }) },
        { whole: p2.w, n: p2.n, d: p2.d, flavor: f2, text: fmtMixedText({ whole: p2.w, n: p2.n, d: p2.d }) }
      ],
      lcd: lcd,
      conv1N: conv1N,
      conv2N: conv2N,
      sumWhole: sumWhole,
      sumFracN: sumFracN,
      totalMixed: totalMixed,
      totalText: fmtMixedText(totalMixed),
      totalHtml: fmtMixedHtml(totalMixed),
      perPerson: perPerson,
      perPersonText: fmtMixedText(perPerson),
      perPersonHtml: fmtMixedHtml(perPerson)
    };
  }

  var setA = buildSet('A', 'Set A (3 People)', 3, 'Friend + 2 siblings (3 people)', chosen.a1, chosen.a2, flavors[0], flavors[1]);
  var setB = buildSet('B', 'Set B (2 People)', 2, 'Friend + 1 sibling (2 people)', chosen.b1, chosen.b2, flavors[2], flavors[3]);
  var setC = buildSet('C', 'Set C (1 Person)', 1, 'You alone (1 person)', chosen.c1, chosen.c2, flavors[4], flavors[5]);

  var sets = [setA, setB, setC];
  var commonDen = lcm(lcm(setA.perPerson.impD, setB.perPerson.impD), setC.perPerson.impD);

  sets.forEach(function(s) {
    s.compNum = s.perPerson.impN * (commonDen / s.perPerson.impD);
    s.compWhole = Math.floor(s.compNum / commonDen);
    s.compRem = s.compNum % commonDen;
    s.compHtml = fmtMixedHtml({ whole: s.compWhole, n: s.compRem, d: commonDen });
  });

  var sorted = sets.slice().sort(function(x, y) { return y.compNum - x.compNum; });
  var winner = sorted[0];

  return {
    sets: sets,
    commonDen: commonDen,
    winnerId: winner.id,
    winnerLabel: winner.label,
    winnerDesc: winner.personDesc,
    winnerServingHtml: winner.perPersonHtml,
    winnerServingText: winner.perPersonText
  };
})()

pie_display.formula:
(function(){
  function drawFullPie(cx, cy, r, flavor) {
    var svg = '';
    svg += '<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="' + flavor.crust + '" stroke="#5c3d1e" stroke-width="1.5"/>';
    svg += '<circle cx="' + cx + '" cy="' + cy + '" r="' + (r - 5) + '" fill="' + flavor.fill + '" stroke="' + flavor.rim + '" stroke-width="1.5"/>';
    svg += '<circle cx="' + cx + '" cy="' + cy + '" r="' + (r - 13) + '" fill="none" stroke="' + flavor.dot + '" stroke-width="1.2" stroke-dasharray="3 4" opacity="0.7"/>';
    return svg;
  }

  function renderPieStack(item) {
    var w = item.whole;
    var n = item.n;
    var d = item.d;
    var f = item.flavor;
    var r = 38;
    var offset = 13;
    var totalW = 92 + w * offset;
    var totalH = 98 + w * 4;
    var frontCx = 46 + w * offset;
    var frontCy = 48 + w * 2;

    var svg = '<svg width="' + totalW + '" height="' + totalH + '" viewBox="0 0 ' + totalW + ' ' + totalH + '" style="display:block;margin:0 auto">';

    for (var k = w; k >= 1; k--) {
      var bx = frontCx - k * offset;
      var by = frontCy - k * 2;
      svg += drawFullPie(bx, by, r, f);
    }

    svg += '<circle cx="' + frontCx + '" cy="' + frontCy + '" r="' + r + '" fill="#f4f6f8" stroke="#cbd5e1" stroke-width="1.2" stroke-dasharray="3 2"/>';

    var frac = n / d;
    var angle = frac * 2 * Math.PI;
    var startAngle = -Math.PI / 2;
    var endAngle = startAngle + angle;
    var x1 = frontCx + r * Math.cos(startAngle);
    var y1 = frontCy + r * Math.sin(startAngle);
    var x2 = frontCx + r * Math.cos(endAngle);
    var y2 = frontCy + r * Math.sin(endAngle);
    var largeArc = frac > 0.5 ? 1 : 0;

    var ir = r - 5;
    var ix1 = frontCx + ir * Math.cos(startAngle);
    var iy1 = frontCy + ir * Math.sin(startAngle);
    var ix2 = frontCx + ir * Math.cos(endAngle);
    var iy2 = frontCy + ir * Math.sin(endAngle);

    var crustPath = 'M ' + frontCx + ' ' + frontCy + ' L ' + x1.toFixed(2) + ' ' + y1.toFixed(2) + ' A ' + r + ' ' + r + ' 0 ' + largeArc + ' 1 ' + x2.toFixed(2) + ' ' + y2.toFixed(2) + ' Z';
    var fillPath = 'M ' + frontCx + ' ' + frontCy + ' L ' + ix1.toFixed(2) + ' ' + iy1.toFixed(2) + ' A ' + ir + ' ' + ir + ' 0 ' + largeArc + ' 1 ' + ix2.toFixed(2) + ' ' + iy2.toFixed(2) + ' Z';

    svg += '<path d="' + crustPath + '" fill="' + f.crust + '" stroke="#5c3d1e" stroke-width="1.5"/>';
    svg += '<path d="' + fillPath + '" fill="' + f.fill + '" stroke="' + f.rim + '" stroke-width="1.2"/>';

    for (var s = 1; s < d; s++) {
      var sa = startAngle + (s / d) * 2 * Math.PI;
      var sx = frontCx + r * Math.cos(sa);
      var sy = frontCy + r * Math.sin(sa);
      svg += '<line x1="' + frontCx + '" y1="' + frontCy + '" x2="' + sx.toFixed(2) + '" y2="' + sy.toFixed(2) + '" stroke="#ffffff" stroke-width="1" opacity="0.6"/>';
    }

    var badgeW = 46;
    var badgeH = 26;
    var bx0 = frontCx - badgeW / 2;
    var by0 = frontCy - badgeH / 2;
    svg += '<rect x="' + bx0 + '" y="' + by0 + '" width="' + badgeW + '" height="' + badgeH + '" rx="6" fill="rgba(255,255,255,0.95)" stroke="#202b36" stroke-width="1.5"/>';
    svg += '<text x="' + (frontCx - 8) + '" y="' + (frontCy + 5) + '" font-family="Arial,sans-serif" font-size="14" font-weight="bold" fill="#202b36" text-anchor="middle">' + w + '</text>';
    svg += '<text x="' + (frontCx + 10) + '" y="' + (frontCy - 2) + '" font-family="Arial,sans-serif" font-size="10" font-weight="bold" fill="#202b36" text-anchor="middle">' + n + '</text>';
    svg += '<line x1="' + (frontCx + 3) + '" y1="' + frontCy + '" x2="' + (frontCx + 17) + '" y2="' + frontCy + '" stroke="#202b36" stroke-width="1.3"/>';
    svg += '<text x="' + (frontCx + 10) + '" y="' + (frontCy + 10) + '" font-family="Arial,sans-serif" font-size="10" font-weight="bold" fill="#202b36" text-anchor="middle">' + d + '</text>';

    svg += '</svg>';
    return '<div style="text-align:center;flex:1;min-width:110px">' + svg + '<div style="font-size:11px;color:#59636e;margin-top:2px">' + f.name + '</div></div>';
  }

  var cols = scenario.sets.map(function(setObj) {
    var piesHtml = setObj.items.map(renderPieStack).join('');
    return '<div style="flex:1;min-width:230px;border:1.5px solid #cbd5e1;border-radius:8px;background:#ffffff;padding:10px 8px;box-sizing:border-box">' +
      '<div style="text-align:center;font-weight:bold;font-size:14px;color:#202b36;background:#e8eef3;padding:5px;border-radius:5px;margin-bottom:8px">' + setObj.label + '</div>' +
      '<div style="display:flex;justify-content:space-around;align-items:center;gap:4px">' + piesHtml + '</div>' +
    '</div>';
  }).join('');

  return '<div style="display:flex;flex-wrap:wrap;gap:12px;width:100%;font-family:Arial,sans-serif;margin-top:10px">' + cols + '</div>';
})()

solution_steps.formula:
(function(){
  function fmtFrac(n, d) {
    return '<span style="display:inline-flex;flex-direction:column;vertical-align:middle;font-size:0.85em;line-height:1.05;text-align:center"><span style="border-bottom:1.5px solid currentColor;padding:0 2px">' + n + '</span><span>' + d + '</span></span>';
  }
  function fmtMix(w, n, d) {
    if (w > 0 && n > 0) return w + '<span style="margin-left:3px">' + fmtFrac(n, d) + '</span>';
    if (w > 0) return String(w);
    return fmtFrac(n, d);
  }

  var step1 = scenario.sets.map(function(s) {
    var p1 = s.items[0], p2 = s.items[1];
    var addLine = fmtMix(p1.w, p1.n, p1.d) + ' + ' + fmtMix(p2.w, p2.n, p2.d);
    if (p1.d !== p2.d) {
      addLine += ' = ' + fmtMix(p1.w, s.conv1N, s.lcd) + ' + ' + fmtMix(p2.w, s.conv2N, s.lcd);
    }
    addLine += ' = ' + fmtMix(s.sumWhole, s.sumFracN, s.lcd);
    if (s.sumWhole !== s.totalMixed.whole || s.sumFracN !== s.totalMixed.n || s.lcd !== s.totalMixed.d) {
      addLine += ' = <b>' + s.totalHtml + '</b>';
    } else {
      addLine = addLine.replace('= ' + fmtMix(s.sumWhole, s.sumFracN, s.lcd), '= <b>' + s.totalHtml + '</b>');
    }
    return '<li style="margin-bottom:6px"><b>' + s.label + ':</b> ' + addLine + ' total pies</li>';
  }).join('');

  var step2 = scenario.sets.map(function(s) {
    var impFrac = fmtFrac(s.totalMixed.impN, s.totalMixed.impD);
    var divLine = s.totalHtml + ' &divide; ' + s.people;
    if (s.people > 1) {
      divLine += ' = ' + impFrac + ' &times; ' + fmtFrac(1, s.people) + ' = ' + fmtFrac(s.totalMixed.impN, s.totalMixed.impD * s.people) + ' = <b>' + s.perPersonHtml + '</b>';
    } else {
      divLine += ' = <b>' + s.perPersonHtml + '</b>';
    }
    return '<li style="margin-bottom:6px"><b>' + s.label + '</b> (' + s.personDesc + '): ' + divLine + ' pie per serving</li>';
  }).join('');

  var step3 = scenario.sets.map(function(s) {
    return '<li style="margin-bottom:4px"><b>' + s.label + ':</b> ' + s.perPersonHtml + ' = <b>' + s.compHtml + '</b></li>';
  }).join('');

  return '<div style="font-family:Arial,sans-serif;font-size:13px;color:#202b36;line-height:1.6">' +
    '<p style="margin:0 0 6px 0"><b>Step 1: Find the total amount of pie in each set.</b></p>' +
    '<ul style="margin:0 0 12px 0;padding-left:20px">' + step1 + '</ul>' +
    '<p style="margin:0 0 6px 0"><b>Step 2: Divide each total by the number of people sharing that set.</b></p>' +
    '<ul style="margin:0 0 12px 0;padding-left:20px">' + step2 + '</ul>' +
    '<p style="margin:0 0 6px 0"><b>Step 3: Compare the serving sizes using a common denominator (' + scenario.commonDen + ').</b></p>' +
    '<ul style="margin:0 0 12px 0;padding-left:20px">' + step3 + '</ul>' +
    '<div style="background:#e8eef3;border-left:4px solid #202b36;padding:8px 12px;border-radius:4px">' +
      '<b>Conclusion:</b> <b>' + scenario.winnerLabel + '</b> (' + scenario.winnerDesc + ') received the most pie per serving at <b>' + scenario.winnerServingHtml + '</b> of a pie per person.' +
    '</div>' +
  '</div>';
})()

data.formula:
(function(){
  var initial_roster = 61 + Math.floor(Math.random() * 38); // 61 to 98
  var late_arrivals = 2 + Math.floor(Math.random() * 5);
  var early_pickups = 1 + Math.floor(Math.random() * 4);
  var expected_total = initial_roster + late_arrivals - early_pickups;

  // Locations away from the main recess yard
  var classroom_initial = 8 + Math.floor(Math.random() * 8);
  var classroom_correction = (Math.random() < 0.5 ? 1 : -1) * (1 + Math.floor(Math.random() * 3));
  var classroom_actual = classroom_initial + classroom_correction;

  var art_room = 5 + Math.floor(Math.random() * 6);
  var music_room = 4 + Math.floor(Math.random() * 6);
  var restroom_initial = 2 + Math.floor(Math.random() * 4);
  var restroom_returned = 1 + Math.floor(Math.random() * 2);
  var restroom_actual = restroom_initial - restroom_returned;

  var nurse_office = 1 + Math.floor(Math.random() * 3);
  var library_initial = 4 + Math.floor(Math.random() * 6);
  var library_correction = (Math.random() < 0.5 ? 1 : -1) * (1 + Math.floor(Math.random() * 2));
  var library_actual = library_initial + library_correction;

  var indoor_total = classroom_actual + art_room + music_room + restroom_actual + nurse_office + library_actual;

  // Decide if everyone is accounted for (50%) or 1 to 3 campers are missing (50%)
  var is_missing = Math.random() < 0.5;
  var missing_count = is_missing ? (1 + Math.floor(Math.random() * 3)) : 0;

  var yard_actual = expected_total - indoor_total - missing_count;
  var yard_miscount_diff = (Math.random() < 0.5 ? 1 : -1) * (2 + Math.floor(Math.random() * 4));
  var yard_first_count = yard_actual + yard_miscount_diff;

  var total_accounted = yard_actual + indoor_total;

  return {
    initial_roster: initial_roster,
    late_arrivals: late_arrivals,
    early_pickups: early_pickups,
    expected_total: expected_total,
    classroom_initial: classroom_initial,
    classroom_correction: classroom_correction,
    classroom_actual: classroom_actual,
    art_room: art_room,
    music_room: music_room,
    restroom_initial: restroom_initial,
    restroom_returned: restroom_returned,
    restroom_actual: restroom_actual,
    nurse_office: nurse_office,
    library_initial: library_initial,
    library_correction: library_correction,
    library_actual: library_actual,
    indoor_total: indoor_total,
    yard_first_count: yard_first_count,
    yard_miscount_diff: yard_miscount_diff,
    yard_actual: yard_actual,
    total_accounted: total_accounted,
    is_missing: is_missing,
    missing_count: missing_count
  };
})()

story_html.formula:
(function(){
  var d = data;
  var class_corr_text = d.classroom_correction > 0
    ? 'actually brought <b>' + d.classroom_correction + ' more</b> campers than initially reported (for a corrected total of <b>' + d.classroom_actual + '</b>)'
    : 'misspoke and actually took <b>' + Math.abs(d.classroom_correction) + ' fewer</b> campers than initially reported (for a corrected total of <b>' + d.classroom_actual + '</b>)';

  var lib_corr_text = d.library_correction > 0
    ? 'the librarian calls to say <b>' + d.library_correction + ' additional</b> camper(s) slipped in with that group'
    : 'the librarian calls to say <b>' + Math.abs(d.library_correction) + '</b> of those campers never arrived and stayed outside';

  var yard_corr_text = d.yard_miscount_diff > 0
    ? 'you realize you double-counted <b>' + d.yard_miscount_diff + '</b> campers running near the swings'
    : 'you realize you missed a group of <b>' + Math.abs(d.yard_miscount_diff) + '</b> campers sitting behind the slide';

  return 'You are a counselor at an elementary camp and you have recess duty. Because there is no fence and there is a large lake, your responsibility is to ensure all the children are accounted for. You arrive and are requested to confirm the count.' +
    '<ul style="line-height:1.6">' +
    '<li><b>Morning Roster &amp; Office Log:</b> The morning attendance sheet started with <b>' + d.initial_roster + '</b> campers. Since check-in, <b>' + d.late_arrivals + '</b> late campers arrived at the front desk, and <b>' + d.early_pickups + '</b> campers were signed out early by parents.</li>' +
    '<li><b>Classroom &amp; Specials:</b> Ms. Alvarez initially radioed that she took <b>' + d.classroom_initial + '</b> campers into Room 104 for reading, but later corrected her message to clarify she ' + class_corr_text + '. Additionally, <b>' + d.art_room + '</b> campers are in the art room working on clay projects, and <b>' + d.music_room + '</b> campers are practicing percussion in the music room.</li>' +
    '<li><b>Library Update:</b> A volunteer walked <b>' + d.library_initial + '</b> campers to the library, though ' + lib_corr_text + '.</li>' +
    '<li><b>Restroom &amp; Nurse:</b> You sent <b>' + d.restroom_initial + '</b> campers to the hallway restrooms, and <b>' + d.restroom_returned + '</b> of them have already returned to the recess yard. Meanwhile, <b>' + d.nurse_office + '</b> camper(s) are resting in the nurse&apos;s office.</li>' +
    '<li><b>Recess Yard Sweep:</b> On your first sweep of the recess field, you count <b>' + d.yard_first_count + '</b> campers. Before submitting your report, ' + yard_corr_text + '.</li>' +
    '</ul>' +
    'Determine the exact expected camp attendance, the corrected count in each location, and whether all children are accounted for (or how many are missing).';
})()
